import heapq


def shortestDistances(n, roads, src):
    adj = [[] for _ in range(n)]
    for a, b, w in roads:
        adj[a].append((b, w))
    INF = float('inf')
    dist = [INF] * n
    dist[src] = 0
    heap = [(0, src)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return [d if d < INF else -1 for d in dist]
